import React from "react";
import "./LeadKanban.css";

const statusConfig = {
  new: { label: "Mới", color: "#3498db" },
  processing: { label: "Đang xử lý", color: "#f1c40f" },
  converted: { label: "Chuyển đổi", color: "#2ecc71" },
  lost: { label: "Mất", color: "#e74c3c" },
};

const LeadKanban = ({ leads, onStatusChange, onDelete }) => {
  return (
    <div className="kanban-wrapper">
      {Object.keys(statusConfig).map((status) => {
        const cfg = statusConfig[status];
        const columnLeads = leads.filter((l) => l.status === status);
        return (
          <div className="kanban-column" key={status}>
            <div
              className="kanban-column-header"
              style={{ backgroundColor: cfg.color }}
            >
              <span>{cfg.label}</span>
              <span className="lead-count">{columnLeads.length}</span>
            </div>
            <div className="kanban-column-body">
              {columnLeads.length === 0 ? (
                <div className="empty-state">Không có lead</div>
              ) : (
                columnLeads.map((lead) => (
                  <div className="kanban-card" key={lead._id}>
                    <div className="lead-header">
                      <h4>{lead.name}</h4>
                      <button onClick={() => onDelete(lead._id)}>🗑</button>
                    </div>
                    <div className="lead-info">
                      <p>📧 {lead.email}</p>
                      <p>📞 {lead.phone}</p>
                    </div>
                    <div className="lead-footer">
                      <select
                        value={lead.status}
                        onChange={(e) =>
                          onStatusChange(lead._id, e.target.value)
                        }
                      >
                        {Object.entries(statusConfig).map(([k, v]) => (
                          <option key={k} value={k}>
                            {v.label}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default LeadKanban;
